    from ansible.module_utils.six import string_types

    class FakeTemplar(object):
        def template(self, data):
            if isinstance(data, dict):
                return dict((k, self.template(v)) for k, v in iteritems(data))
            if isinstance(data, string_types) and data.startswith('{{') and data.endswith('}}'):
                return 'resolved-' + data.strip('{} ').strip()
            return data

    action = ActionModule.__new__(ActionModule)
    action._templar = FakeTemplar()

    argument_spec = {
        'name': {'type': 'str'},
        'count': {'type': 'int'},
        'unused': {'type': 'str', 'default': 'x'},
    }

    task_vars = {
        'name': '{{ host_name }}',
        'count': 3,
        'not_in_spec': 'should be ignored',
    }

    result = action.get_args_from_task_vars(argument_spec, task_vars)

    assert result == {'name': 'resolved-host_name', 'count': 3}, result
    assert 'unused' not in result, result
    assert 'not_in_spec' not in result, result
